INSERT OR REPLACE INTO product_reviews (id, product_id, user_id, reviewer_name, sku_option_summary, rating, content, images_json, helpful_count, is_verified_purchase, created_at, order_id, author_name, user_height_cm, user_weight_kg, fit_type, photo_urls_json) VALUES ('rev_003', 'prod_001', 'u_customer_001', 'Park S.H.', 'White / 기본', 4.9, '올모아에서 첫 구매인데 테무보다 배송 빠르고 포장도 튼튼하게 왔어요. 재구매 의사 100%입니다.', '[]', 9, 1, '2026-10-09 06:35:36', NULL, NULL, NULL, NULL, 'TRUE_TO_SIZE', NULL);
INSERT OR REPLACE INTO product_reviews (id, product_id, user_id, reviewer_name, sku_option_summary, rating, content, images_json, helpful_count, is_verified_purchase, created_at, order_id, author_name, user_height_cm, user_weight_kg, fit_type, photo_urls_json) VALUES ('rev_004', 'prod_m_03', 'u_customer_001', '최*영', '블랙 / L (100)', 4.9, '원단이 짱짱하고 방수도 잘 됩니다. 가볍고 핏이 예뻐서 등산갈 때 잘 입고 있어요.', '["https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=300"]', 14, 1, '2026-10-15 06:35:36', NULL, NULL, NULL, NULL, 'TRUE_TO_SIZE', NULL);
