INSERT OR REPLACE INTO product_reviews (id, product_id, user_id, reviewer_name, sku_option_summary, rating, content, images_json, helpful_count, is_verified_purchase, created_at, order_id, author_name, user_height_cm, user_weight_kg, fit_type, photo_urls_json) VALUES ('rev_006', 'prod_002', 'u_customer_001', '한*민', '65W 3-Port / 블랙', 4.9, '맥북 프로랑 아이폰 동시에 물려도 발열이 거의 없고 충전 속도가 정말 빠릅니다. 크기도 작아서 출장 필수템이에요!', '["https://images.unsplash.com/photo-1583863788434-e58a36330cf0?w=300"]', 29, 1, '2026-10-22 08:32:02', NULL, NULL, NULL, NULL, 'TRUE_TO_SIZE', NULL);
INSERT OR REPLACE INTO product_reviews (id, product_id, user_id, reviewer_name, sku_option_summary, rating, content, images_json, helpful_count, is_verified_purchase, created_at, order_id, author_name, user_height_cm, user_weight_kg, fit_type, photo_urls_json) VALUES ('rev_007', 'prod_003', 'u_customer_001', '오*주', '4-Pieces 세트', 4.8, '버튼 한 번만 누르면 알아서 진공을 잡아줘서 샐러드 야채가 일주일 넘게 아삭합니다. 냉장고 정리하기 딱 좋아요.', '["https://images.unsplash.com/photo-1584269600464-37b1b58a9fe7?w=300"]', 19, 1, '2026-10-21 08:32:02', NULL, NULL, NULL, NULL, 'TRUE_TO_SIZE', NULL);
INSERT OR REPLACE INTO product_reviews (id, product_id, user_id, reviewer_name, sku_option_summary, rating, content, images_json, helpful_count, is_verified_purchase, created_at, order_id, author_name, user_height_cm, user_weight_kg, fit_type, photo_urls_json) VALUES ('rev_008', 'prod_004', 'u_customer_001', '강*현', '블랙 / L', 4.9, '기모가 부드럽고 세탁기 돌려도 목 늘어남이나 수축이 전혀 없네요. 그레이 색상도 추가 구매했습니다.', '["https://images.unsplash.com/photo-1556905055-8f358a7a47b2?w=300"]', 42, 1, '2026-10-23 08:32:02', NULL, NULL, NULL, NULL, 'TRUE_TO_SIZE', NULL);
INSERT OR REPLACE INTO product_reviews (id, product_id, user_id, reviewer_name, sku_option_summary, rating, content, images_json, helpful_count, is_verified_purchase, created_at, order_id, author_name, user_height_cm, user_weight_kg, fit_type, photo_urls_json) VALUES ('rev_009', 'prod_w_01', 'u_customer_001', '윤*아', '베이지 / M', 4.9, '플리츠 주름이 고급스럽고 허리 리본 묶으면 라인이 정말 예쁩니다. 결혼식 하객룩으로 최고예요.', '[]', 21, 1, '2026-10-20 08:32:02', NULL, NULL, NULL, NULL, 'TRUE_TO_SIZE', NULL);
